import{_ as t,o as i,c as a,a5 as n}from"./chunks/framework.BF53ZjCA.js";const f=JSON.parse('{"title":"Identification Workflow & Documentation","description":"","frontmatter":{"title":"Identification Workflow & Documentation","identification":"identification-workflow"},"headers":[],"relativePath":"identification/identification-workflow.md","filePath":"identification/identification-workflow.md","lastUpdated":1789230763000}'),o={name:"identification/identification-workflow.md"};function r(s,e,c,d,l,p){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="identification-workflow-documentation" tabindex="-1">Identification Workflow &amp; Documentation <a class="header-anchor" href="#identification-workflow-documentation" aria-label="Permalink to &quot;Identification Workflow &amp; Documentation&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Professional identification is not a search for one “magic reading”; it is a reproducible chain of evidence. Record the sample first, begin with low-risk observations, combine physical, optical, and inclusion clues, then state the confidence limits, treatment disclosure, and whether a laboratory report is needed.</p><h2 id="identification-steps" tabindex="-1">Identification Steps <a class="header-anchor" href="#identification-steps" aria-label="Permalink to &quot;Identification Steps&quot;">​</a></h2><p><strong>1. Record the sample and scope</strong></p><p>Note dimensions, weight, mounting, known provenance, visible damage, and the purpose of the examination. Record which tests are unreliable or unavailable for mounted, oiled, or inaccessible samples.</p><p><strong>2. Start with non-destructive observation</strong></p><p>Under white light, a point source, and suitable magnification, record body color, transparency, luster, cut, inclusions, and phenomena. Write observations before candidate names.</p><p><strong>3. Escalate tests by risk</strong></p><p>Prefer refractive index, polariscope, dichroscope, UV fluorescence, and spectroscopy as non-destructive clues. Assess whether a specific-gravity liquid test is suitable; scratch testing requires a clear need and permission.</p><p><strong>4. Cross-check and grade the conclusion</strong></p><p>Compare readings with candidate ranges, treatment possibilities, and sample limitations. Distinguish “supports a candidate”, “consistent with a candidate”, and “cannot exclude”; a single test is not a final ID.</p><p><strong>5. Refer to a laboratory when needed</strong></p><p>For natural-versus-synthetic decisions, origin opinions, major transactions, or insurance, preserve raw observations and refer the sample to a qualified laboratory for advanced testing.</p><h2 id="core-principles" tabindex="-1">Core Principles <a class="header-anchor" href="#core-principles" aria-label="Permalink to &quot;Core Principles&quot;">​</a></h2><ul><li>Keep separate fields for “what was observed” and “what it suggests” so observation and conclusion do not contaminate each other.</li><li>Record test conditions, orientation, contact state, and repeated readings; values cannot be compared without context.</li><li>Keep the conclusion weaker than the evidence: a screen is not a certificate, and an origin opinion is not a grade.</li><li>Confirm permission, sample value, and safety conditions before any destructive test.</li></ul><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gem</th><th>Value</th><th>Note</th></tr></thead><tbody><tr><td>mounted ruby</td><td>screen first; report inaccessible tests</td><td>mounting limits access</td></tr></tbody></table><p><em>See the <a href="./intro.html">identification overview</a>.</em></p>',19)])])}const u=t(o,[["render",r]]);export{f as __pageData,u as default};
